// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testFuzz_property(address u, uint256 amount) public {
        vm.assume(u != address(0));
        amount = bound(amount, 1, type(uint256).max);
        vm.deal(u, amount);
        vm.prank(u);
        c.addToBalance{value: amount}();
        uint256 bal = c.getBalance(u);
        assertTrue(bal == amount);
    }
}
